class GitHubError(RuntimeError):
    """A safe, classified GitHub operation failure."""

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        transient: bool = False,
        stdout: str = "",
    ) -> None:
        super().__init__(message)
        self.status = status
        self.transient = transient
        self.stdout = stdout


